// undoAvailable applies the recovery scope to every Undo entry point.
func undoAvailable(data PageData) bool {
	return data.CanUndo && (!data.RecoveryPending || data.UndoDir != "")
}

// undoLabel says where Undo acts once the user has moved to another folder, so
// the button is never a surprise about which files it touches.
func undoLabel(data PageData) string {
	if data.UndoDir == "" {
		return "Undo"
	}
	return "Undo rename in “" + baseName(data.UndoDir) + "”"
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func renameChangeCount(data PageData) int {
	if data.ChangedCount > 0 {
		return data.ChangedCount
	}
	n := 0
	for _, p := range data.Previews {
		if p.OriginalName != p.NewName {
			n++
		}
	}
	return n
}

